/* * To change this template, choose Tools | Templates * and open the template in the editor. */package net.sf.jiga.xtended.ui;import java.awt.event.ActionEvent;import java.awt.event.ActionListener;import java.awt.event.MouseAdapter;import java.awt.event.MouseEvent;import java.lang.management.ManagementFactory;import java.lang.management.MemoryUsage;import net.sf.jiga.xtended.impl.Sprite;import net.sf.jiga.xtended.impl.system.BufferIO;import net.sf.jiga.xtended.impl.system.ImagePool;/** * * @author www.b23prodtm.info */public class MemStatusToolkit {    final JProgressMemory memStatus = new JProgressMemory(0, 100), heapStatus = new JProgressMemory(0, 100);    final javax.swing.Timer mem;    public JProgressMemory getMemStatus() {        if (!mem.isRunning()) {            mem.start();        }        return memStatus;    }    public JProgressMemory getHeapMemStatus() {        if (!mem.isRunning()) {            mem.start();        }        return heapStatus;    }    @Override    protected void finalize() throws Throwable {        super.finalize();        mem.stop();    }    public MemStatusToolkit() {        memStatus.setDoubleBuffered(true);        memStatus.setStringPainted(true);        memStatus.setString("RAM");        heapStatus.setDoubleBuffered(true);        heapStatus.setStringPainted(true);        heapStatus.setString("VM");        heapStatus.setToolTipText("Click to free some memory space !");        heapStatus.addMouseListener(new MouseAdapter() {            @Override            public void mouseEntered(MouseEvent e) {                super.mouseEntered(e);                heapStatus.setOpaque(!heapStatus.isOpaque());            }            @Override            public void mouseExited(MouseEvent e) {                super.mouseExited(e);                heapStatus.setOpaque(!heapStatus.isOpaque());            }            @Override            public void mouseClicked(MouseEvent e) {                super.mouseClicked(e);                System.gc();                System.runFinalization();                System.gc();            }        });        mem = new javax.swing.Timer((int) (1000f / 30f), new ActionListener() {            public void actionPerformed(ActionEvent e) {                boolean mod = _updateJPMem(memStatus, _getNonHeap());                if (mod) {                    /*Sprite._quickPaintImmediately(memStatus);*/                    memStatus.repaint();                }                mod = _updateJPMem(heapStatus, _getHeap());                if (mod) {                    /*Sprite._quickPaintImmediately(heapStatus);*/                    heapStatus.repaint();                }            }        });    }    public static double percentOfMaxPermittedHeapUsage = 80;    public static MemoryUsage _getNonHeap() {        return ManagementFactory.getMemoryMXBean().getNonHeapMemoryUsage();    }    public static MemoryUsage _getHeap() {        return ManagementFactory.getMemoryMXBean().getHeapMemoryUsage();    }    /** this sets up a JProgressMemory instance to display values got from a MemoryUsage instance and BufferIO and Sprite pools byteSize (init value)     * @return true if the progressbar should be repainted, because of changes for MemoryUsage */    public static boolean _updateJPMem(JProgressMemory memory, MemoryUsage mem) {        int max = (int) mem.getMax(), val = (int) mem.getUsed(), val_init = (int) (ImagePool.getImagePoolByteSize() + BufferIO.getPool_stackByteSize()), val_committed = (int) mem.getCommitted();        boolean mod = false;        mod = mod || memory.getMaximum() != max;        memory.setMaximum(max);        memory.setMaximum_init(max);        memory.setMaximum_committed(max);        mod = mod || memory.getValue() != val;        memory.setValue(val);        mod = mod || memory.getValue_init() != val_init;        memory.setValue_init(Math.max(0, Math.min(max, (int) mem.getInit())));        mod = mod || memory.getValue_committed() != val_committed;        memory.setValue_committed((int) mem.getCommitted());        return mod;    }}